export const handler = async (input) => {
  const coverage = Number(input.evidence_coverage || 0);
  const verification = String(input.verification_status || 'UNKNOWN').toUpperCase();
  const score = Number(input.final_score || 0);
  let score_eligibility = 'INSUFFICIENT_EVIDENCE';
  if (verification === 'VERIFIED_BUSINESS' && coverage >= 60) score_eligibility = 'ELIGIBLE';
  else if (coverage >= 25 || verification === 'VERIFIED_BUSINESS' || verification === 'REVIEW') score_eligibility = 'PARTIAL_EVIDENCE';
  const qualification_status = verification === 'REJECTED' ? 'REJECTED' : (score_eligibility === 'ELIGIBLE' && score >= 55 ? 'QUALIFIED' : 'REVIEW');
  const reason_codes = [score_eligibility === 'ELIGIBLE' ? 'SCORE_EVIDENCE_ELIGIBLE' : score_eligibility === 'PARTIAL_EVIDENCE' ? 'SCORE_EVIDENCE_PARTIAL' : 'SCORE_EVIDENCE_INSUFFICIENT'];
  if (verification !== 'VERIFIED_BUSINESS') reason_codes.push('BUSINESS_VERIFICATION_NOT_COMPLETE');
  return { score_eligibility, qualification_status, reason_codes, rule_version: 'qualification-v1' };
};
